### 15. Add seed data
Create `ShipmentTracker/Data/SeedData.cs` that seeds some sample shipments if the database is empty. Call it from Program.cs after building the app (using a scope to get the DbContext).

```csharp
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Data;

public static class SeedData
{
    public static async Task InitializeAsync(IServiceProvider services)
    {
        using var scope = services.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
        await db.Database.EnsureCreatedAsync();

        if (db.Shipments.Any()) return;

        db.Shipments.AddRange(
            new Shipment { TrackingNumber = "TRK-7A3F9B21", Origin = "New York, US", Destination = "London, UK", Status = ShipmentStatus.InTransit, ShippedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(4), CustomerEmail = "alice@example.com", Description = "Electronics - Laptop" },
            new Shipment { TrackingNumber = "TRK-4C8E2D56", Origin = "Shanghai, CN", Destination = "Los Angeles, US", Status = ShipmentStatus.OutForDelivery, ShippedDate = DateTime.UtcNow.AddDays(-10), EstimatedDelivery = DateTime.UtcNow.AddDays(1), CustomerEmail = "bob@example.com", Description = "Furniture - Office Desk" },
            new Shipment { TrackingNumber = "TRK-9F1A7E34", Origin = "Berlin, DE", Destination = "Tokyo, JP", Status = ShipmentStatus.Pending, ShippedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(7), CustomerEmail = "carol@example.com", Description = "Auto Parts" },
            new Shipment { TrackingNumber = "TRK-2B5D8C90", Origin = "Sydney, AU", Destination = "Mumbai, IN", Status = ShipmentStatus.Delivered, ShippedDate = DateTime.UtcNow.AddDays(-14), EstimatedDelivery = DateTime.UtcNow.AddDays(-2), CustomerEmail = "dave@example.com", Description = "Textiles - Cotton Fabric" },
            new Shipment { TrackingNumber = "TRK-6E4G1H78", Origin = "São Paulo, BR", Destination = "Paris, FR", Status = ShipmentStatus.Delayed, ShippedDate = DateTime.UtcNow.AddDays(-7), EstimatedDelivery = DateTime.UtcNow.AddDays(3), CustomerEmail = "eve@example.com", Description = "Food Products - Coffee Beans" }
        );

        await db.SaveChangesAsync();
    }
}
```

In Program.cs, right before `app.Run();`, add:
```csharp
await SeedData.InitializeAsync(app.Services);
```

